effect.shader:

//vec2 projectAndClamp(vec2 a, vec2 b) {
//    return clamp(dot(a,b)/dot(b,b),0.0,1.0) * b;
//}
vec2 project(vec2 a, vec2 b) {
    return (dot(a,b)/dot(b,b)) * b;
}

float smoothstepRev(float edge0, float edge1, float x) {
    if(edge0 == edge1) return step(edge0, x);
    else return smoothstep(edge0, edge1, x);
}

void main() {
    float adjStart = start;
    float adjEnd = end;
    float adjFeather = feather/100.0;
    float radwipe = angleb * 0.0174533;
    vec2 v = normalize(vec2(cos(radwipe),-sin(radwipe)));
    //vec2 v = (vec4(normalize(vec2(cos(radwipe),-sin(radwipe))),0.0,1.0) * acLayerToScreen).xy;
    //float p = length(projectAndClamp(acLayerNorm.st-vec2(0.5,0.5), v))/length(v)+0.5;
    float p = dot(acLayerNorm.st-vec2(0.5,0.5), v)+0.5;

    float p0 = smoothstepRev(adjStart-adjFeather,adjStart,p);
    float p1 = 1. - smoothstepRev(adjEnd,adjEnd+adjFeather,p);

    float rad = anglea* 0.0174533;
    mat2 rot = mat2(cos(rad),-sin(rad),sin(rad),cos(rad));
    mat2 invrot = mat2(cos(-rad),-sin(-rad),sin(-rad),cos(-rad));

    vec2 sampleCoord = ((((acLayerNorm - 0.5) * rot) * vec2((1.0/scale), 1.0)) * invrot) + 0.5;
    sampleCoord = (vec4(sampleCoord,0.0,1.0) * acLayerToScreen).xy;

    //////////////////////////
    if ( pinch ) {
    vec2 center = acLayerCenterNorm-(centerPoint/1000. * vec2(-1.,1.));

    sampleCoord -= center;
    sampleCoord.x *= acScreenSize.x / acScreenSize.y;
    float dist = length(sampleCoord);
    if ( dist < radius ) {
        float p = dist / radius;
        if(strength > 0.) {
            sampleCoord *= mix(1.0, smoothstep(0.0, radius / dist, p), strength * 0.75);
        } else {
            sampleCoord *= mix(1.0, pow(p, 1.0 + strength * 0.75) * radius / dist, 1.0 - p);
        }
    }
    sampleCoord.x /= acScreenSize.x / acScreenSize.y;
    sampleCoord += center;
    }
    //////////////////////////

    vec4 texColor;
    if( umefx ) {
    texColor = texture2DCv(inputImg.texture,sampleCoord) *p0*p1*alpha;
    } else {
    texColor = texture2DCv(inputImg.texture,sampleCoord) * alpha;
    }

    vec4 result;
    if( blendMode==1 ) {
        result = vec4((texColor.rgb/texColor.a)*color.rgb,1.0) * texColor.a;
    } else if( blendMode==2 ) {
        result = vec4( 1.-((1.-(texColor.rgb/texColor.a))*(1.-color.rgb)),1.0) * texColor.a;
    } else {
        result = vec4(color.rgb,1.0)*texColor.a;
    }
    gl_FragColor = mix(texColor,result,alphaa);
}
